-- Isolated fixtures; all changes roll back. Run after the admin-owned-store migration.
begin;
create temp table admin_store_results(result text);
do $$
declare a uuid;b uuid:=gen_random_uuid();device uuid;placed jsonb;payload jsonb;config jsonb;photo text;bucket_path text;blocked boolean;
begin
 select user_id into a from public.user_roles where role='admin' limit 1;
 if a is null then raise exception 'An existing admin is required';end if;
 insert into auth.users(id,email,email_confirmed_at,aud,role,raw_user_meta_data) values(b,'qa-store-'||b||'@example.invalid',now(),'authenticated','authenticated','{}');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_save_store_settings('{"name":"QA Store","tagline":"QA","email":"qa@example.invalid","phone":"9000000000","city":"Bangalore","address":"QA store address Bangalore 560001","pickup_instructions":"Bring your order number","delivery_available":true,"pickup_available":true,"delivery_fee":100,"delivery_pincodes":["560001"]}');
 bucket_path:=a::text||'/'||gen_random_uuid()||'.webp';
 insert into storage.objects(bucket_id,name,metadata) values('marketplace-images',bucket_path,'{"mimetype":"image/webp","size":1000}');
 photo:='https://pdwdonojugtersushxtv.supabase.co/storage/v1/object/public/marketplace-images/'||bucket_path;
 payload:=jsonb_build_object('title','QA Latitude','brand','Dell','category','laptop','price',18000,'year',null,'condition','Good','description','QA laptop with complete specifications and disclosed condition.','processor','Intel Core i5','ram','8 GB','storage','256 GB SSD','graphics','Integrated','display','14 inch','battery','Works','defects','Normal cosmetic wear','accessories','Charger','seller_warranty_months',0,'warranty_terms','','images',jsonb_build_array(photo),'stock_quantity',2,'status','draft');
 execute 'set local role authenticated';
 if not public.marketplace_can_upload() then raise exception 'Admin image upload denied';end if;
 device:=public.admin_save_store_product(null,payload);
 if not exists(select 1 from public.marketplace_listings where id=device and store_owned and status='draft') then raise exception 'Draft failed';end if;
 perform public.admin_save_store_product(device,payload||'{"status":"published"}');
 if not exists(select 1 from public.marketplace_listings where id=device and review_status='approved' and status='published' and verified_at is null and (commission_terms->>'seller_net')::numeric=0) then raise exception 'Direct publication failed';end if;
 perform public.admin_save_store_product(device,payload||'{"status":"published","price":19000}');
 if not exists(select 1 from public.marketplace_listings where id=device and price=19000 and status='published') then raise exception 'Edit failed';end if;
 perform public.admin_save_store_product(device,payload||'{"status":"published","price":19000,"delivery_available":true,"delivery_fee":75,"delivery_pincodes":["560002"]}');
 if not exists(select 1 from public.marketplace_listings where id=device and delivery_fee=100 and delivery_pincodes=array['560001']) then raise exception 'Listing failed to inherit store delivery settings';end if;
 blocked:=false;begin perform public.admin_save_store_product(device,payload||'{"delivery_available":true,"delivery_pincodes":["invalid"]}');exception when others then blocked:=true;end;if not blocked then raise exception 'Invalid delivery pincode accepted';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if public.marketplace_can_upload() then raise exception 'Buyer image upload allowed';end if;
 blocked:=false;begin perform public.admin_save_store_product(null,payload);exception when others then blocked:=true;end;if not blocked then raise exception 'Buyer created inventory';end if;
 blocked:=false;begin perform public.admin_save_store_settings('{}');exception when others then blocked:=true;end;if not blocked then raise exception 'Buyer edited store';end if;
 blocked:=false;begin perform public.marketplace_save_device(null,payload,'{}',false,0);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Legacy seller RPC accessible';end if;
 placed:=public.marketplace_place_order(gen_random_uuid(),jsonb_build_array(jsonb_build_object('listing_id',device,'quantity',1,'fulfillment_method','pickup')),'{"name":"QA Buyer","phone":"9000000001"}',19000,true);
 execute 'reset role';
 if not exists(select 1 from public.marketplace_orders where listing_id=device and amount=19000 and seller_net=0) then raise exception 'Checkout total failed';end if;
 if not exists(select 1 from public.marketplace_listings where id=device and stock_available=1) then raise exception 'Stock reservation failed';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 select to_jsonb(s) into config from public.store_settings s where id;
 perform public.admin_save_store_settings(config||'{"delivery_fee":150,"pickup_hours":"Monday to Saturday, 10am to 6pm","delivery_estimate":"2â€“4 working days","delivery_terms":"We call before delivery."}');
 if not exists(select 1 from public.marketplace_listings where id=device and delivery_fee=150 and status='published') then raise exception 'Global fulfilment edit lost publication';end if;
 if not exists(select 1 from public.store_settings where pickup_hours='Monday to Saturday, 10am to 6pm' and delivery_terms='We call before delivery.') then raise exception 'Pickup hours or delivery terms were not saved';end if;
 perform public.admin_save_store_settings('{"name":"QA Renamed Store","tagline":"QA","email":"qa@example.invalid","phone":"9000000000","city":"Bangalore","address":"QA store address Bangalore 560001","delivery_available":false,"pickup_available":true,"delivery_fee":0,"delivery_pincodes":[]}');
 if not exists(select 1 from public.marketplace_listings where id=device and seller_name='QA Renamed Store' and status='published') then raise exception 'Store rename failed';end if;
 if not exists(select 1 from public.marketplace_listings where id=device and delivery_available=false and delivery_fee=0) then raise exception 'Global settings did not update a listing with active orders';end if;
 if not exists(select 1 from public.marketplace_orders where listing_id=device and amount=19000 and product_snapshot->>'pickup_address'='QA store address Bangalore 560001') then raise exception 'Placed order details changed';end if;
 perform public.admin_delete_store_product(device);
 if not exists(select 1 from public.marketplace_orders where listing_id=device) then raise exception 'Deletion lost order history';end if;
 insert into admin_store_results values('PASS: drafts, direct publishing, editing, admin permissions, legacy RPC denial, checkout, stock, rename, history-preserving deletion');
end $$;
select * from admin_store_results;
rollback;
